<?php
require_once __DIR__ . '/config/database.php'; require_once __DIR__ . '/includes/layout.php';
$email=filter_var(trim($_POST['email']??$_GET['email']??''),FILTER_VALIDATE_EMAIL);$code=preg_replace('/\D/','',(string)($_POST['code']??$_GET['code']??''));$error='';$valid=false;$resetId=0;
if($email&&preg_match('/^\d{6}$/',$code)){$q=$pdo->prepare('SELECT pr.id,pr.otp_hash FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE u.email=? AND pr.consumed_at IS NULL AND pr.expires_at>NOW() ORDER BY pr.id DESC LIMIT 1');$q->execute([$email]);$row=$q->fetch();if($row&&password_verify($code,$row['otp_hash'])){$valid=true;$resetId=(int)$row['id'];}else $error='That code is invalid or expired. Request a new one.';}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$password=$_POST['password']??'';$confirm=$_POST['confirm_password']??'';if(!$email||!preg_match('/^\d{6}$/',$code))$error='Enter your email and valid reset code.';elseif(strlen($password)<10)$error='Use a password with at least 10 characters.';elseif($password!==$confirm)$error='The passwords do not match.';else{$pdo->beginTransaction();try{$q=$pdo->prepare('SELECT pr.id,pr.otp_hash,pr.user_id FROM password_resets pr JOIN users u ON u.id=pr.user_id WHERE u.email=? AND pr.consumed_at IS NULL AND pr.expires_at>NOW() ORDER BY pr.id DESC LIMIT 1 FOR UPDATE');$q->execute([$email]);$row=$q->fetch();if(!$row||!password_verify($code,$row['otp_hash']))throw new RuntimeException('That code is invalid or expired. Request a new one.');$pdo->prepare('UPDATE users SET password_hash=? WHERE id=?')->execute([password_hash($password,PASSWORD_DEFAULT),$row['user_id']]);$pdo->prepare('UPDATE password_resets SET consumed_at=NOW() WHERE user_id=? AND consumed_at IS NULL')->execute([$row['user_id']]);$pdo->commit();flash('Password updated. Sign in with your new password.');redirect('login.php');}catch(Throwable $e){$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'Could not update the password.';}}}
if(!$valid&&$_SERVER['REQUEST_METHOD']!=='POST')$error='Open this page with the email and reset code from your message.';
start_page('Choose a new password'); ?><section class="card auth-card"><p class="eyebrow">ACCOUNT RECOVERY</p><h1 class="card-title mt-2 text-2xl">Choose a new password</h1><?php if($error): ?><div class="alert alert-error mt-4"><?= e($error) ?></div><?php endif ?><?php if($valid||$_SERVER['REQUEST_METHOD']==='POST'): ?><form method="post" class="mt-6 space-y-4"><?= csrf_field() ?><input type="hidden" name="email" value="<?= e($email?:'') ?>"><input type="hidden" name="code" value="<?= e($code) ?>"><div><label class="field-label" for="password">New password</label><div class="password-wrap"><input class="field" id="password" name="password" type="password" minlength="10" required><button type="button" class="eye-toggle" data-password-toggle="password" aria-label="Show password"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div><div><label class="field-label" for="confirm_password">Confirm new password</label><div class="password-wrap"><input class="field" id="confirm_password" name="confirm_password" type="password" minlength="10" required><button type="button" class="eye-toggle" data-password-toggle="confirm_password" aria-label="Show password"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div></div><button class="btn-primary w-full">Update password</button></form><?php endif ?></section><?php end_page(); ?>
